<template><el-dialog :model-value="store.isOpen" title="变更用户套餐" width="min(520px, 92vw)" trap-focus :close-on-click-modal="false" @open="onOpen" @open-auto-focus="focusFirst" @close="requestClose" @closed="onClosed" @keydown.esc.capture.stop.prevent="requestClose"><template v-if="store.target"><el-alert v-if="store.state==='conflict'" ref="errorAlert" tabindex="-1" type="warning" :closable="false" title="用户信息已变化，正在刷新，请重新确认。"/><el-alert v-else-if="store.failureCode" ref="errorAlert" tabindex="-1" type="error" :closable="false" title="请求无法完成，请重新确认后重试。"/><el-alert type="info" :closable="false" title="此操作只调整服务套餐，不创建订单或付款记录。"/><el-form id="admin-user-plan-change-form" ref="formRef" :model="form" :rules="rules" label-position="top" scroll-to-error @submit.prevent="submit"><el-form-item prop="planType" label="新套餐"><el-select ref="selectInput" v-model="form.planType" :disabled="busy"><el-option v-for="plan in options" :key="plan.value" :label="plan.label" :value="plan.value" :disabled="plan.value===store.target.planType"/></el-select></el-form-item><el-form-item prop="reason" label="变更原因"><el-input v-model="form.reason" type="textarea" :rows="3" :disabled="busy"/></el-form-item></el-form></template><template #footer><el-button @click="requestClose">取消</el-button><el-button type="primary" native-type="submit" form="admin-user-plan-change-form" :loading="busy" :disabled="busy">确认变更</el-button></template></el-dialog></template>
<script setup>
import{computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch}from'vue';import{useAdminUserPlanChangeStore,ADMIN_USER_PLAN_OPTIONS as options}from'@/stores/admin-user-plan-change';import{normalizePlanChangeRequest}from'@/api/admin-user-entitlements';const props=defineProps({owner:{type:Object,default:null}}),emit=defineEmits(['closed','succeeded','conflict','failed']),store=useAdminUserPlanChangeStore(),formRef=ref(null),selectInput=ref(null),errorAlert=ref(null),form=reactive({planType:'',reason:''});let visibleOwner=null,closingOwner=null;const busy=computed(()=>store.state==='submitting');const rules={planType:[{required:true,message:'请选择新套餐',trigger:'change'}],reason:[{validator:(_r,_v,d)=>{const n=[...form.reason.trim()].length;n>=1&&n<=200?d():d(new Error('请输入 1–200 个字符的原因'))},trigger:['blur','change']}]};function clear(){form.planType='';form.reason='';formRef.value?.clearValidate?.()}function focusFirst(e){e?.preventDefault?.();const t=props.owner;nextTick(()=>nextTick(()=>{if(store.owns(t))selectInput.value?.focus?.()}))}function onOpen(){visibleOwner=props.owner;clear();focusFirst()}function requestClose(){if(store.owns(props.owner)){closingOwner=props.owner;store.close(props.owner)}}function onClosed(){const t=closingOwner??visibleOwner;closingOwner=null;if(store.isOpen)return;visibleOwner=null;clear();emit('closed',t)}async function submit(){const t=props.owner;if(!store.owns(t)||busy.value)return;if(['failed','conflict'].includes(store.state))store.reset(t);try{await formRef.value.validate()}catch{return}let input;try{input=normalizePlanChangeRequest({targetGuid:store.target.guid,planType:form.planType,reason:form.reason,expectedAuthVersion:store.target.authVersion})}catch{return}const r=await store.submit(t,{planType:input.planType,reason:input.reason});if(!store.owns(t)||!r)return;if(r.state==='succeeded'){emit('succeeded',r.user,t);requestClose()}else if(r.state==='conflict')emit('conflict',t);else{emit('failed',r.failureCode,t);nextTick(()=>errorAlert.value?.$el?.focus?.())}}function onEscape(e){if(e.key==='Escape'&&store.owns(props.owner)){e.preventDefault();e.stopPropagation();requestClose()}}onMounted(()=>document.addEventListener('keydown',onEscape,true));onBeforeUnmount(()=>document.removeEventListener('keydown',onEscape,true));watch(()=>store.dialogRevision,()=>{if(store.isOpen)onOpen()});watch(()=>store.isOpen,(v,o)=>{if(!v&&o&&!closingOwner)closingOwner=visibleOwner??props.owner},{flush:'sync'})
</script>
